            <button class="btn-danger-sm" @onclick="() => OnRemove.InvokeAsync()">Remove</button>
        }
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Name *</label>
            <input type="text" value="@Entry.Name" @oninput="e => Update(Entry with { Name = (string?)e.Value ?? "" })" />
        </div>
        <div class="form-group">
            <label>Relationship *</label>
            <input type="text" value="@Entry.Relationship" @oninput="e => Update(Entry with { Relationship = (string?)e.Value ?? "" })" />
        </div>
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Email *</label>
            <input type="email" value="@Entry.Email" @oninput="e => Update(Entry with { Email = (string?)e.Value ?? "" })" />
        </div>
        <div class="form-group">
            <label>Phone *</label>
            <input type="tel" value="@Entry.Phone" @oninput="e => Update(Entry with { Phone = (string?)e.Value ?? "" })" />
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public ReferenceModel Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback<ReferenceModel> OnChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private void Update(ReferenceModel updated) => OnChanged.InvokeAsync(updated);

    public record ReferenceModel(string Name, string Relationship, string Email, string Phone)
    {
        public static ReferenceModel Empty() => new("", "", "", "");
    }
}

@namespace sv_9b8a152a2e954ad98b6f1262cfabc070.Components.Pages.Apply

<h3>References</h3>
<p class="hint">Please provide 2–3 professional references.</p>

@for (int i = 0; i < References.Count; i++)
{
    var index = i;
    <ReferenceForm Entry="@References[index]"
                   Index="index"
                   CanRemove="@(References.Count > 2)"
                   OnChanged="e => UpdateReference(index, e)"
                   OnRemove="() => RemoveReference(index)" />
}

@if (References.Count < 3)
{
    <button class="btn-secondary" @onclick="AddReference">+ Add Reference</button>
}

@if (!string.IsNullOrEmpty(ErrorMessage))
{
    <div class="error-message">@ErrorMessage</div>
}

<div class="step-buttons">
    <button class="btn-outline" @onclick="() => OnBack.InvokeAsync()">Back</button>
    <button class="btn-primary" @onclick="HandleNext">Next</button>
</div>

@code {
    [Parameter] public List<ReferenceForm.ReferenceModel> References { get; set; } = [ReferenceForm.ReferenceModel.Empty(), ReferenceForm.ReferenceModel.Empty()];
    [Parameter] public EventCallback<List<ReferenceForm.ReferenceModel>> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? ErrorMessage;

    private void AddReference()
    {
        if (References.Count < 3)
        {
            References.Add(ReferenceForm.ReferenceModel.Empty());
        }
    }

    private void RemoveReference(int index)
    {
        if (References.Count > 2)
        {
            References.RemoveAt(index);
        }
    }

    private void UpdateReference(int index, ReferenceForm.ReferenceModel updated)
    {
        References[index] = updated;
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;
        foreach (var r in References)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship)
                || string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
            {
                ErrorMessage = "All reference fields are required.";
                return;
            }
        }
        await OnNext.InvokeAsync(References);
    }
}

@namespace sv_9b8a152a2e954ad98b6f1262cfabc070.Components.Pages.Apply

<h3>Cover Letter</h3>

<div class="form-group">
    <textarea id="coverLetter" rows="12" maxlength="2000"
              @bind="CoverLetter" @bind:event="oninput"
              placeholder="Write your cover letter here..."></textarea>
    <div class="char-count">@CoverLetter.Length / 2000 characters</div>
</div>

@if (!string.IsNullOrEmpty(ErrorMessage))
{
    <div class="error-message">@ErrorMessage</div>
}

<div class="step-buttons">
    <button class="btn-outline" @onclick="() => OnBack.InvokeAsync()">Back</button>
    <button class="btn-primary" @onclick="HandleNext">Next</button>
</div>

@code {
    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter] public EventCallback<string> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? ErrorMessage;

    private async Task HandleNext()
    {
        ErrorMessage = null;
        if (string.IsNullOrWhiteSpace(CoverLetter))
        {
            ErrorMessage = "Please write a cover letter.";
            return;
        }
        await OnNext.InvokeAsync(CoverLetter);
    }
}

@namespace sv_9b8a152a2e954ad98b6f1262cfabc070.Components.Pages.Apply
@using sv_9b8a152a2e954ad98b6f1262cfabc070.Models

<h3>Review & Submit</h3>

@if (IsSubmitted)
{
    <div class="confirmation">
        <h4>✓ Application Submitted!</h4>
        <p>Your application ID is: <strong>@ApplicationId</strong></p>
        <p>Thank you for applying. We will be in touch soon.</p>
    </div>
}
else
{
    <section class="review-section">
        <div class="review-header">
            <h4>Personal Information</h4>
            <button class="btn-link" @onclick="() => OnEditStep.InvokeAsync(0)">Edit</button>
        </div>
        <dl>
            <dt>Name</dt><dd>@Personal.FullName</dd>
            <dt>Email</dt><dd>@Personal.Email</dd>
            <dt>Phone</dt><dd>@Personal.Phone</dd>
            <dt>Address</dt><dd>@Personal.Address</dd>
        </dl>
    </section>

    <section class="review-section">
        <div class="review-header">
            <h4>Work History</h4>
            <button class="btn-link" @onclick="() => OnEditStep.InvokeAsync(1)">Edit</button>
        </div>
        @foreach (var entry in WorkEntries)
        {
            <div class="review-work-entry">
                <strong>@entry.Title</strong> at @entry.Company
                <br />
                <span class="text-muted">
                    @entry.StartDate.ToString("MMM yyyy") –
                    @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")
                </span>
                @if (!string.IsNullOrWhiteSpace(entry.Description))
                {
                    <p>@entry.Description</p>
                }
            </div>
        }
    </section>

    <section class="review-section">
        <div class="review-header">
            <h4>References</h4>
            <button class="btn-link" @onclick="() => OnEditStep.InvokeAsync(2)">Edit</button>
        </div>
        @foreach (var r in References)
        {
            <div class="review-reference">
                <strong>@r.Name</strong> (@r.Relationship)
                <br />@r.Email | @r.Phone
            </div>
        }
    </section>

    <section class="review-section">
        <div class="review-header">
            <h4>Cover Letter</h4>
            <button class="btn-link" @onclick="() => OnEditStep.InvokeAsync(3)">Edit</button>
        </div>
        <p class="cover-letter-preview">@CoverLetter</p>
    </section>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="error-message">@ErrorMessage</div>
    }

    <div class="step-buttons">
        <button class="btn-outline" @onclick="() => OnBack.InvokeAsync()">Back</button>
        <button class="btn-primary btn-submit" @onclick="HandleSubmit" disabled="@IsSubmitting">
            @(IsSubmitting ? "Submitting..." : "Submit Application")
        </button>
    </div>
}

@code {
