<h3>Personal Information</h3>

<div class="form-group">
    <label for="fullName">Full Name *</label>
    <input id="fullName" type="text" @bind="FullName" @bind:event="oninput" />
</div>

<div class="form-group">
    <label for="email">Email *</label>
    <input id="email" type="email" @bind="Email" @bind:event="oninput" />
</div>

<div class="form-group">
    <label for="phone">Phone *</label>
    <input id="phone" type="tel" @bind="Phone" @bind:event="oninput" />
</div>

<div class="form-group">
    <label for="address">Address *</label>
    <textarea id="address" @bind="Address" @bind:event="oninput" rows="3"></textarea>
</div>

@if (!string.IsNullOrEmpty(ErrorMessage))
{
    <div class="error-message">@ErrorMessage</div>
}

<div class="step-buttons">
    <button class="btn-primary" @onclick="HandleNext" disabled="@IsValidating">
        @if (IsValidating)
        {
            <span>Validating...</span>
        }
        else
        {
            <span>Next</span>
        }
    </button>
</div>

@code {
    [Parameter] public string FullName { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Phone { get; set; } = "";
    [Parameter] public string Address { get; set; } = "";
    [Parameter] public EventCallback<PersonalInfoResult> OnNext { get; set; }

    private string? ErrorMessage;
    private bool IsValidating;

    [Inject] private IApplicationService ApplicationService { get; set; } = default!;

    private async Task HandleNext()
    {
        ErrorMessage = null;

        if (string.IsNullOrWhiteSpace(FullName))
        {
            ErrorMessage = "Full name is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(Email))
        {
            ErrorMessage = "Email is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(Phone))
        {
            ErrorMessage = "Phone is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(Address))
        {
            ErrorMessage = "Address is required.";
            return;
        }

        IsValidating = true;
        try
        {
            var isEmailValid = await ApplicationService.ValidateEmailAsync(Email);
            if (!isEmailValid)
            {
                ErrorMessage = "The email address is not valid.";
                return;
            }

            await OnNext.InvokeAsync(new PersonalInfoResult(FullName, Email, Phone, Address));
        }
        finally
        {
            IsValidating = false;
        }
    }

    public record PersonalInfoResult(string FullName, string Email, string Phone, string Address);
}
"}

{"path": "/tmp/sv-9b8a152a2e954ad98b6f1262cfabc070/Components/Pages/Apply/WorkEntryForm.razor", "file_text": "@namespace sv_9b8a152a2e954ad98b6f1262cfabc070.Components.Pages.Apply

<div class="work-entry">
    <div class="work-entry-header">
        <h4>Position @(Index + 1)</h4>
        @if (CanRemove)
        {
            <button class="btn-danger-sm" @onclick="() => OnRemove.InvokeAsync()">Remove</button>
        }
    </div>

    <div class="form-group">
        <label>Company Name *</label>
        <input type="text" value="@Entry.Company" @oninput="e => Update(Entry with { Company = (string?)e.Value ?? "" })" />
    </div>

    <div class="form-group">
        <label>Job Title *</label>
        <input type="text" value="@Entry.Title" @oninput="e => Update(Entry with { Title = (string?)e.Value ?? "" })" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" value="@Entry.StartDate.ToString("yyyy-MM-dd")" @onchange="e => Update(Entry with { StartDate = DateTime.Parse((string?)e.Value ?? DateTime.Today.ToString("yyyy-MM-dd")) })" />
        </div>

        <div class="form-group">
            <label>End Date</label>
            <input type="date" value="@Entry.EndDate?.ToString("yyyy-MM-dd")" @onchange="e => Update(Entry with { EndDate = string.IsNullOrEmpty((string?)e.Value) ? null : DateTime.Parse((string)e.Value) })" disabled="@IsCurrent" />
            <label class="checkbox-label">
                <input type="checkbox" checked="@IsCurrent" @onchange="HandleCurrentChanged" />
                Currently working here
            </label>
        </div>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea rows="3" value="@Entry.Description" @oninput="e => Update(Entry with { Description = (string?)e.Value ?? "" })"></textarea>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public WorkEntryModel Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback<WorkEntryModel> OnChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private bool IsCurrent => Entry.IsCurrent;

    private void Update(WorkEntryModel updated) => OnChanged.InvokeAsync(updated);

    private void HandleCurrentChanged(ChangeEventArgs e)
    {
        var isCurrent = (bool)(e.Value ?? false);
        var updated = Entry with { IsCurrent = isCurrent, EndDate = isCurrent ? null : Entry.EndDate };
        OnChanged.InvokeAsync(updated);
    }

    public record WorkEntryModel(string Company, string Title, DateTime StartDate, DateTime? EndDate, bool IsCurrent, string Description)
    {
        public static WorkEntryModel Empty() => new("", "", DateTime.Today, null, false, "");
    }
}
"}

