.step-indicator ol {
    display: flex;
    align-items: center;
    list-style: none;
    padding: 0;
    margin: 0 0 2rem 0;
}

.step {
    display: flex;
    flex-direction: column;
    align-items: center;
    cursor: default;
    opacity: 0.4;
    transition: opacity 0.2s;
}

.step.active {
    opacity: 1;
}

.step.completed {
    opacity: 1;
    cursor: pointer;
}

.step.dimmed {
    opacity: 0.4;
}

.step-circle {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    background: #e0e0e0;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 0.9rem;
    margin-bottom: 0.4rem;
}

.step.active .step-circle {
    background: #1976d2;
    color: white;
}

.step.completed .step-circle {
    background: #4caf50;
    color: white;
}

.step-label {
    font-size: 0.75rem;
    text-align: center;
    max-width: 80px;
}

.step-connector {
    flex: 1;
    height: 2px;
    background: #e0e0e0;
    margin: 0 0.5rem;
    margin-bottom: 1.5rem;
}

.step-connector.completed {
    background: #4caf50;
}

.checkmark {
    font-size: 1rem;
}

