@namespace sv_9b8a152a2e954ad98b6f1262cfabc070.Components.Pages.Apply
@using sv_9b8a152a2e954ad98b6f1262cfabc070.Models

<h3>Personal Information</h3>

<div class="form-group">
    <label for="fullName">Full Name *</label>
    <input id="fullName" type="text" @bind="FullName" @bind:event="oninput" />
</div>

<div class="form-group">
    <label for="email">Email *</label>
    <input id="email" type="email" @bind="Email" @bind:event="oninput" />
</div>

<div class="form-group">
    <label for="phone">Phone *</label>
    <input id="phone" type="tel" @bind="Phone" @bind:event="oninput" />
</div>

<div class="form-group">
    <label for="address">Address *</label>
    <textarea id="address" @bind="Address" @bind:event="oninput" rows="3"></textarea>
</div>

@if (!string.IsNullOrEmpty(ErrorMessage))
{
    <div class="error-message">@ErrorMessage</div>
}

<div class="step-buttons">
    <button class="btn-primary" @onclick="HandleNext" disabled="@IsValidating">
        @if (IsValidating)
        {
            <span>Validating...</span>
        }
        else
        {
            <span>Next</span>
        }
    </button>
</div>

@code {
    [Parameter] public string FullName { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Phone { get; set; } = "";
    [Parameter] public string Address { get; set; } = "";
    [Parameter] public EventCallback<PersonalInfoResult> OnNext { get; set; }

    private string? ErrorMessage;
    private bool IsValidating;

    [Inject] private IApplicationService ApplicationService { get; set; } = default!;

    private async Task HandleNext()
    {
        ErrorMessage = null;

        if (string.IsNullOrWhiteSpace(FullName))
        {
            ErrorMessage = "Full name is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(Email))
        {
            ErrorMessage = "Email is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(Phone))
        {
            ErrorMessage = "Phone is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(Address))
        {
            ErrorMessage = "Address is required.";
            return;
        }

        IsValidating = true;
        try
        {
            var isEmailValid = await ApplicationService.ValidateEmailAsync(Email);
            if (!isEmailValid)
            {
                ErrorMessage = "The email address is not valid.";
                return;
            }

            await OnNext.InvokeAsync(new PersonalInfoResult(FullName, Email, Phone, Address));
        }
        finally
        {
            IsValidating = false;
        }
    }

    public record PersonalInfoResult(string FullName, string Email, string Phone, string Address);
}

