+++ b/tmp/sv-9b8a152a2e954ad98b6f1262cfabc070/Components/Pages/Apply/ApplyPage.razor
@@ -1,0 +1,122 @@
+@page "/apply"
+@namespace sv_9b8a152a2e954ad98b6f1262cfabc070.Components.Pages.Apply
+@rendermode InteractiveServer
+@using sv_9b8a152a2e954ad98b6f1262cfabc070.Models
+
+<PageTitle>Job Application</PageTitle>
+
+<div class="apply-container">
+    <h2>Job Application</h2>
+
+    <StepIndicator CurrentStep="currentStep"
+                   StepNames="stepNames"
+                   CompletedSteps="completedSteps"
+                   OnStepSelected="GoToStep" />
+
+    @switch (currentStep)
+    {
+        case 0:
+            <PersonalInfoStep FullName="@personalFullName"
+                              Email="@personalEmail"
+                              Phone="@personalPhone"
+                              Address="@personalAddress"
+                              OnNext="HandlePersonalInfoNext" />
+            break;
+
+        case 1:
+            <WorkHistoryStep Entries="workEntries"
+                             OnNext="HandleWorkHistoryNext"
+                             OnBack="GoBack" />
+            break;
+
+        case 2:
+            <ReferencesStep References="references"
+                            OnNext="HandleReferencesNext"
+                            OnBack="GoBack" />
+            break;
+
+        case 3:
+            <CoverLetterStep CoverLetter="@coverLetter"
+                             OnNext="HandleCoverLetterNext"
+                             OnBack="GoBack" />
+            break;
+
+        case 4:
+            <ReviewStep Personal="@personalInfo!"
+                        WorkEntries="workEntries"
+                        References="references"
+                        CoverLetter="@coverLetter"
+                        OnEditStep="GoToStep"
+                        OnBack="GoBack" />
+            break;
+    }
+</div>
+
+@code {
+    private static readonly IReadOnlyList<string> stepNames = ["Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"];
+
+    private int currentStep;
+    private HashSet<int> completedSteps = new();
+
+    // Personal Info state
+    private string personalFullName = "";
+    private string personalEmail = "";
+    private string personalPhone = "";
+    private string personalAddress = "";
+    private PersonalInfoStep.PersonalInfoResult? personalInfo;
+
+    // Work History state
+    private List<WorkEntryForm.WorkEntryModel> workEntries = [WorkEntryForm.WorkEntryModel.Empty()];
+
+    // References state
+    private List<ReferenceForm.ReferenceModel> references = [ReferenceForm.ReferenceModel.Empty(), ReferenceForm.ReferenceModel.Empty()];
+
+    // Cover Letter state
+    private string coverLetter = "";
+
+    private void HandlePersonalInfoNext(PersonalInfoStep.PersonalInfoResult result)
+    {
+        personalFullName = result.FullName;
+        personalEmail = result.Email;
+        personalPhone = result.Phone;
+        personalAddress = result.Address;
+        personalInfo = result;
+        completedSteps.Add(0);
+        currentStep = 1;
+    }
+
+    private void HandleWorkHistoryNext(List<WorkEntryForm.WorkEntryModel> entries)
+    {
+        workEntries = entries;
+        completedSteps.Add(1);
+        currentStep = 2;
+    }
+
+    private void HandleReferencesNext(List<ReferenceForm.ReferenceModel> refs)
+    {
+        references = refs;
+        completedSteps.Add(2);
+        currentStep = 3;
+    }
+
+    private void HandleCoverLetterNext(string letter)
+    {
+        coverLetter = letter;
+        completedSteps.Add(3);
+        currentStep = 4;
+    }
+
+    private void GoToStep(int step)
+    {
+        currentStep = step;
+    }
+
+    private void GoBack()
+    {
+        if (currentStep > 0)
+        {
+            currentStep--;
+        }
+    }
+}
+

toolArgs.file_text:
.apply-container {
    max-width: 720px;
    margin: 2rem auto;
    padding: 0 1rem;
}

h2 {
    margin-bottom: 1.5rem;
}

h3 {
    margin-bottom: 1rem;
    color: #333;
}

.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.3rem;
    font-weight: 500;
    font-size: 0.9rem;
}

.form-group input,
.form-group textarea {
    width: 100%;
    padding: 0.5rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 0.95rem;
    box-sizing: border-box;
}

.form-group textarea {
    resize: vertical;
}

.form-row {
    display: flex;
    gap: 1rem;
}

.form-row .form-group {
    flex: 1;
}

.checkbox-label {
    display: inline-flex !important;
    align-items: center;
    gap: 0.4rem;
    font-weight: normal !important;
    margin-top: 0.4rem;
}

.checkbox-label input[type="checkbox"] {
    width: auto;
}

.step-buttons {
    display: flex;
    justify-content: space-between;
    margin-top: 2rem;
    gap: 1rem;
}

.btn-primary {
    background: #1976d2;
    color: white;
    border: none;
    padding: 0.6rem 1.5rem;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.95rem;
}

.btn-primary:hover:not(:disabled) {
    background: #1565c0;
}

.btn-primary:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-outline {
    background: transparent;
    color: #1976d2;
    border: 1px solid #1976d2;
    padding: 0.6rem 1.5rem;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.95rem;
}

.btn-outline:hover {
    background: #e3f2fd;
}

.btn-secondary {
    background: #f5f5f5;
    color: #333;
    border: 1px solid #ccc;
    padding: 0.5rem 1rem;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.9rem;
    margin-top: 0.5rem;
}

.btn-secondary:hover {
    background: #e0e0e0;
}

.btn-danger-sm {
    background: #e53935;
    color: white;
    border: none;
    padding: 0.3rem 0.7rem;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.8rem;
}

.btn-danger-sm:hover {
    background: #c62828;
}

.btn-link {
    background: none;
    border: none;
    color: #1976d2;
    cursor: pointer;
    text-decoration: underline;
    font-size: 0.9rem;
    padding: 0;
}

.btn-submit {
    padding: 0.7rem 2rem;
    font-size: 1rem;
}

.error-message {
    color: #d32f2f;
    background: #ffebee;
    padding: 0.6rem 1rem;
    border-radius: 4px;
    margin-top: 1rem;
    font-size: 0.9rem;
}

.hint {
    color: #666;
    font-size: 0.9rem;
    margin-bottom: 1rem;
}

.char-count {
    text-align: right;
    font-size: 0.85rem;
    color: #666;
    margin-top: 0.3rem;
}

.work-entry,
.reference-entry {
    border: 1px solid #e0e0e0;
    border-radius: 6px;
    padding: 1rem;
    margin-bottom: 1rem;
    background: #fafafa;
}

.work-entry-header,
.reference-entry-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.5rem;
}

.work-entry-header h4,
.reference-entry-header h4 {
    margin: 0;
}

/* Review step */
.review-section {
    border-bottom: 1px solid #e0e0e0;
    padding-bottom: 1rem;
    margin-bottom: 1rem;
}

.review-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.review-header h4 {
    margin: 0 0 0.5rem 0;
}

.review-section dl {
    display: grid;
    grid-template-columns: 100px 1fr;
    gap: 0.3rem 1rem;
    margin: 0;
}

.review-section dt {
    font-weight: 500;
    color: #555;
}

.review-section dd {
    margin: 0;
}

.review-work-entry,
.review-reference {
    margin-bottom: 0.75rem;
    padding-left: 0.5rem;
    border-left: 3px solid #e0e0e0;
}

.text-muted {
    color: #666;
    font-size: 0.9rem;
}

.cover-letter-preview {
    white-space: pre-wrap;
    background: #f9f9f9;
    padding: 1rem;
    border-radius: 4px;
    border: 1px solid #eee;
}

.confirmation {
    text-align: center;
    padding: 2rem;
    background: #e8f5e9;
    border-radius: 8px;
    margin-top: 1rem;
}

.confirmation h4 {
    color: #2e7d32;
    font-size: 1.4rem;
    margin-bottom: 1rem;
}

